# -*- coding: utf-8 -*-
"""Unified interface dictionary for AmviBackUp 19.9.7.

All seven language tables have exactly the same keys.  Existing localized phrases
are retained; English is the deliberate safe fallback for phrases not yet localized.
"""
from __future__ import annotations
from dataclasses import dataclass
import re

BASE_LANGUAGE = "en"
REQUIRED_LANGUAGES = frozenset({"en", "ru"})
@dataclass(frozen=True)
class LanguageInfo:
    code: str
    native_name: str
    english_name: str
    rtl: bool = False
LANGUAGES = (
    LanguageInfo("en", "English", "English"),
    LanguageInfo("zh", "中文（简体）", "Chinese (Simplified)"),
    LanguageInfo("hi", "हिन्दी", "Hindi"),
    LanguageInfo("es", "Español", "Spanish"),
    LanguageInfo("fr", "Français", "French"),
    LanguageInfo("ar", "العربية", "Arabic", True),
    LanguageInfo("ru", "Русский", "Russian"),
)
_BY_CODE = {item.code: item for item in LANGUAGES}
def supported_codes(): return tuple(item.code for item in LANGUAGES)
def native_name(code): return _BY_CODE[code].native_name
def is_rtl(code): return bool(_BY_CODE.get(code) and _BY_CODE[code].rtl)

