_RESTORE_DEFAULT_HINT = {
    "en": (
        "The destination folder may contain other files. "
        "Existing files are never overwritten: a conflicting name gets "
        "a '-restored-' suffix with the date and time. "
        "The suggested restore folder is created automatically when needed."
    ),
    "ru": (
        "Папка назначения может содержать другие файлы. "
        "Существующие файлы не перезаписываются: при совпадении имени "
        "добавляются «-restored-», дата и время. "
        "Предложенная папка восстановления при необходимости создаётся автоматически."
    ),
    "zh": (
        "目标文件夹可以包含其他文件。"
        "现有文件绝不会被覆盖：名称冲突时，会添加“-restored-”以及日期和时间。"
        "建议的恢复文件夹会在需要时自动创建。"
    ),
    "hi": (
        "गंतव्य फ़ोल्डर में अन्य फ़ाइलें हो सकती हैं। "
        "मौजूदा फ़ाइलें कभी अधिलेखित नहीं होतीं: नाम टकराने पर "
        "नाम में '-restored-' और तारीख़ व समय जोड़ा जाता है। "
        "सुझाया गया पुनर्स्थापना फ़ोल्डर ज़रूरत पड़ने पर अपने-आप बनाया जाता है।"
    ),
    "es": (
        "La carpeta de destino puede contener otros archivos. "
        "Los archivos existentes nunca se sobrescriben: si un nombre coincide, "
        "se añade el sufijo '-restored-' con la fecha y la hora. "
        "La carpeta de restauración sugerida se crea automáticamente cuando hace falta."
    ),
    "fr": (
        "Le dossier de destination peut contenir d'autres fichiers. "
        "Les fichiers existants ne sont jamais écrasés : en cas de conflit de nom, "
        "le suffixe '-restored-' avec la date et l'heure est ajouté. "
        "Le dossier de restauration proposé est créé automatiquement si nécessaire."
    ),
    "ar": (
        "يمكن أن يحتوي مجلد الوجهة على ملفات أخرى. "
        "لا تُستبدل الملفات الموجودة أبدًا: عند تعارض الاسم، "
        "تُضاف اللاحقة '-restored-' مع التاريخ والوقت. "
        "يُنشأ مجلد الاستعادة المقترح تلقائيًا عند الحاجة."
    ),
}

for _language_code, _hint_text in _RESTORE_DEFAULT_HINT.items():
    TRANSLATIONS[_language_code]["restore_wizard.default_hint"] = _hint_text

