for _support_code, _support_table in _SUPPORT_TRANSLATIONS.items():
    TRANSLATIONS[_support_code].update(_support_table)
del _support_code, _support_table, _SUPPORT_TRANSLATIONS

_PLACEHOLDER = re.compile(r"\{(\w+)\}")
def _placeholders(text): return set(_PLACEHOLDER.findall(text))
def validate():
    problems=[]
    base=TRANSLATIONS[BASE_LANGUAGE]
    for code in supported_codes():
        table=TRANSLATIONS.get(code, {})
        missing=set(base)-set(table)
        extra=set(table)-set(base)
        if missing: problems.append(f"missing {code}: {sorted(missing)!r}")
        if extra: problems.append(f"extra {code}: {sorted(extra)!r}")
        for key in set(base)&set(table):
            if _placeholders(table[key]) != _placeholders(base[key]):
                problems.append(f"placeholders {code} {key}")
    return problems
def coverage(translations=TRANSLATIONS):
    total=len(translations[BASE_LANGUAGE])
    return {code:(len(translations[code]), total, round(100*len(translations[code])/total, 1)) for code in supported_codes()}
def missing_keys(code): return [key for key in TRANSLATIONS[BASE_LANGUAGE] if key not in TRANSLATIONS.get(code,{})]
if __name__ == "__main__":
    problems=validate()
    for code, row in coverage().items(): print(code, *row)
    raise SystemExit(bool(problems))
